from pathlib import Path
from PIL import ImageFont
import json
p=Path(__file__).resolve().parent
cues=[(0,2.22,'혹시 내가 널 아프게 한다 해도','もし僕が君を傷つけても'),(2.22,4.72,'제발 나를 떠나지만 마요.','どうか僕から離れないで'),(4.72,7.1,'소리치며 화를 내도 진심 아니에요','怒鳴って怒っても本心じゃないんだ'),(7.1,10,'제발 나를 떠나지만 마요','どうか僕から離れないで'),(10.22,12.32,'혹시 내가 잠시 한 눈 판다 해도','もし少しよそ見をしてしまっても'),(12.32,14.92,'제발 나를 떠나지만 마요','どうか僕から離れないで'),(14.92,17.42,'내가 잠깐 미쳤었나봐요 맘 아프게','一瞬どうかしてたんだ、君を傷つけて'),(17.42,21.1,'제발 나를 떠나지만 마요 oh','どうか僕から離れないで oh'),(21.72,25.7,'하지만 넌 날 아프게 하는걸','でもあなたは私を傷つける'),(25.7,30.82,'지금도 난 행복하진 않은걸','今だって私は幸せじゃない'),(30.82,33.36,'너를 사랑하지만','あなたを愛しているけれど'),(33.36,35.9,'이제 이쯤에서 그만해','もうこの辺で終わりにしよう'),(35.9,40.1,'나 오늘 너를 떠날꺼야','今日、あなたのもとを去るわ'),(40.7,41.84,'변했다면 미안해','変わってしまったならごめん'),(41.84,43.12,'짜증만 내서 미안해','苛立ってばかりでごめん'),(43.12,44.36,'신경 못써서 미안해','気にかけてあげられなくてごめん'),(44.36,45.64,'미안해 모두 미안해','ごめん、何もかもごめん'),(45.64,46.9,'소리쳐서 미안해','怒鳴ってごめん'),(46.9,48.14,'아프게 해서 미안해','傷つけてごめん'),(48.14,49.08,'미안해서 미안해','謝ってばかりでごめん'),(49.08,50.7,'난 할 말이 없어 정말 미안해','言葉もない、本当にごめん'),(50.7,53.2,'미안해 잘해주지도 못하고 진짜 미안해','大切にできなくて、本当にごめん'),(53.2,55.74,'떠나지도 못하고 널 보내주지도 못해 미안해','離れられず、君を手放せなくてごめん'),(55.74,58.26,'미안해 미안해 너 없이는 안돼 미안해','ごめん、ごめん、君なしじゃ駄目なんだ'),(58.26,62,'행복하지도 못하게 사랑해서 정말 미안해','愛しても幸せにできなくて、本当にごめん')]
def ts(t):
 c=round(t*100);return f'{c//360000}:{c//6000%60:02}:{c//100%60:02}.{c%100:02}'
def st(t):
 m=round(t*1000);return f'{m//3600000:02}:{m//60000%60:02}:{m//1000%60:02},{m%1000:03}'
for end,suffix in [(60,''),(62,'_ending')]:
 s=(p/'layout.ass').read_text().replace('0:01:00.00',ts(end))
 current=[(a,min(b,end),k,j) for a,b,k,j in cues if a<end]
 for a,b,k,j in current:
  for style,text,y,font,size in [('KO',k,1385,'/System/Library/Fonts/AppleSDGothicNeo.ttc',48),('JA',j,1455,'/System/Library/Fonts/ヒラギノ角ゴシック W6.ttc',44)]:
   ft=ImageFont.truetype(font,size);sz=min(size,int(size*900/max(1,ft.getlength(text))))
   s+=f'Dialogue: 0,{ts(a)},{ts(b)},{style},,0,0,0,,{{\\pos(540,{y})\\fs{sz}}}{text}\n'
 (p/f'layout_with_lyrics{suffix}.ass').write_text(s)
 (p.parent/f'KIM_JIN_PYO_Sorry_KO_JA{suffix}.srt').write_text('\n\n'.join(f'{i}\n{st(a)} --> {st(b)}\n{k}\n{j}' for i,(a,b,k,j) in enumerate(current,1))+'\n')
(p/'lyrics.json').write_text(json.dumps(cues,ensure_ascii=False,indent=2))
